import { defineConfig } from "orval";

// `yarn api:generate` regenerates src/generated from openapi.json, which the
// BFF writes from its routes. Never edit src/generated by hand.
const target = process.env.ORVAL_OUT ?? "./src/generated";

export default defineConfig({
  bookings: {
    input: "./openapi.json",
    output: {
      mode: "split",
      target: `${target}/api.ts`,
      client: "react-query",
      httpClient: "fetch",
      mock: { generators: [{ type: "msw", delay: false }] },
      clean: true,
      override: {
        mutator: { path: "./src/fetcher.ts", name: "apiFetch" },
        fetch: { includeHttpResponseReturnType: false },
      },
    },
  },
});
